-- Teldrassil and Shadowglen: creature abilities
-- The Webwood spiders, Gnarlpine Mystic, Grimmaw, the Ancient Protectors and others had no AI and only melee'd, and the Gnarlpine,
-- Bloodfeather and sprite mobs ran classic rows. Port their abilities from the Cataclysm data, and from the classic data where
-- Cataclysm has none (Webwood Lurker, Giant Webwood Spider). The sprites' and Vicious Grell's quest credit scripts are kept.
-- Gnarlpine Shaman's flee and Elder Timberling's Healing Wave had a 0-30000% health range in the Cataclysm data; they use 15% and
-- 30%.

SET @ENTRIES := '1986,1994,1998,1999,2000,2001,2002,2003,2004,2005,2008,2009,2011,2015,2021,2030,2041,2151,7234,7235,14429,34517,34530';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
